import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.BZO4qERu.js";const E=JSON.parse('{"title":"Configuration reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/configuration.md","filePath":"reference/configuration.md","lastUpdated":1791997268000}'),n={name:"reference/configuration.md"};function o(r,e,d,l,p,c){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="configuration-reference" tabindex="-1">Configuration reference <a class="header-anchor" href="#configuration-reference" aria-label="Permalink to &quot;Configuration reference&quot;">​</a></h1><p>There are three configuration layers: deployment defaults, the search form, and the immutable settings saved with a run. Editing today&#39;s form does not change an existing run.</p><h2 id="community-environment-variables" tabindex="-1">Community environment variables <a class="header-anchor" href="#community-environment-variables" aria-label="Permalink to &quot;Community environment variables&quot;">​</a></h2><p>The repository&#39;s <a href="https://github.com/paperseek/paperseek/blob/main/.env.example" target="_blank" rel="noreferrer">.env.example</a> is the deployment template.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Use</th></tr></thead><tbody><tr><td><code>PAPERSEEK_DATABASE</code></td><td>Local SQLite path; defaults to <code>~/.paperseek/paperseek.db</code></td></tr><tr><td><code>PAPERSEEK_LLM_API_TYPE</code></td><td><code>openai_responses</code>, <code>openai_chat</code>, or <code>anthropic_messages</code></td></tr><tr><td><code>PAPERSEEK_LLM_BASE_URL</code></td><td>Provider API base URL</td></tr><tr><td><code>PAPERSEEK_LLM_MODEL</code></td><td>A model ID supported by that provider</td></tr><tr><td><code>PAPERSEEK_LLM_API_KEY</code></td><td>Model credential</td></tr><tr><td><code>PAPERSEEK_OPENALEX_API_KEY</code></td><td>OpenAlex key or key pool</td></tr><tr><td><code>PAPERSEEK_SEMANTIC_SCHOLAR_API_KEY</code></td><td>Optional Semantic Scholar key</td></tr><tr><td><code>PAPERSEEK_PUBMED_API_KEY</code></td><td>Optional NCBI key</td></tr><tr><td><code>PAPERSEEK_WOS_API_KEY</code></td><td>Web of Science Starter key</td></tr><tr><td><code>PAPERSEEK_WOS_DB</code></td><td>WoS collection, for example <code>WOS</code></td></tr><tr><td><code>PAPERSEEK_GOOGLE_SCHOLAR_API_KEY</code></td><td>Serper key or key pool</td></tr><tr><td><code>PAPERSEEK_CONTACT_EMAIL</code></td><td>Contact email used by source clients that support it</td></tr></tbody></table><p>Direct CLI/server execution reads the process environment. Docker Compose loads the optional <code>.env</code> file. A copied template alone does not configure a directly launched Python process.</p><h3 id="example-on-powershell" tabindex="-1">Example on PowerShell <a class="header-anchor" href="#example-on-powershell" aria-label="Permalink to &quot;Example on PowerShell&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PAPERSEEK_LLM_API_TYPE </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;openai_chat&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PAPERSEEK_LLM_BASE_URL </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://your-provider.example/v1&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PAPERSEEK_LLM_MODEL </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;your-model-id&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PAPERSEEK_LLM_API_KEY </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&lt;your-key&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">paperseek serve</span></span></code></pre></div><p>Replace all placeholders. Prefer your operating system or service manager&#39;s private secret configuration for unattended use. The URL above is deliberately not a working provider endpoint.</p><h3 id="openalex-and-serper-key-pools" tabindex="-1">OpenAlex and Serper key pools <a class="header-anchor" href="#openalex-and-serper-key-pools" aria-label="Permalink to &quot;OpenAlex and Serper key pools&quot;">​</a></h3><p>Separate keys with whitespace, commas, or semicolons in the corresponding variable or key field. PaperSeek rotates the starting key and distinguishes authentication failures from transient failures.</p><p>Do not repeat a key to simulate extra capacity. Each provider still enforces its own access policies.</p><h2 id="per-search-settings" tabindex="-1">Per-search settings <a class="header-anchor" href="#per-search-settings" aria-label="Permalink to &quot;Per-search settings&quot;">​</a></h2><p>The form contains the research question, source, fields, budget, model connection, preliminary ranking, and source-specific options. See <a href="./../guide/search">search</a>, <a href="./../guide/sources">data sources</a>, and <a href="./../guide/models">models</a>.</p><p>Protocol and base URL must agree. A server that implements Chat Completions does not necessarily implement Responses or Anthropic Messages. The usual OpenAI-compatible base URL ends in <code>/v1</code>; do not append <code>/chat/completions</code> when the field asks for a base URL.</p><h2 id="optional-ranking-services" tabindex="-1">Optional ranking services <a class="header-anchor" href="#optional-ranking-services" aria-label="Permalink to &quot;Optional ranking services&quot;">​</a></h2><p>Local fusion needs no external preliminary-ranking endpoint. Embedding + Rerank and System One require their corresponding connections when used in Community or with your own key online. Their keys and model IDs can differ from the main language model.</p><h2 id="online-configuration" tabindex="-1">Online configuration <a class="header-anchor" href="#online-configuration" aria-label="Permalink to &quot;Online configuration&quot;">​</a></h2><p>PaperSeek Service provides model lists and server-managed connections. With your own key, public provider connections are allowed after server-side address validation. Deployment secrets, internal routes, and allowlists are operator settings, not end-user fields.</p><p>See the <a href="./../online/">online guide</a>.</p>`,20)])])}const k=a(n,[["render",o]]);export{E as __pageData,k as default};
